DO $$
BEGIN
    IF (SELECT count(*) FROM sites_location WHERE external_id IS NOT NULL) < 4 THEN RAISE EXCEPTION 'Location seed count validation failed'; END IF;
    IF (SELECT count(*) FROM leads_leadsource WHERE external_id IS NOT NULL) < 10 THEN RAISE EXCEPTION 'Lead source seed count validation failed'; END IF;
    IF (SELECT count(*) FROM accounts_user WHERE external_id IS NOT NULL) < 12 THEN RAISE EXCEPTION 'User seed count validation failed'; END IF;
    IF (SELECT count(*) FROM leads_family WHERE external_id IS NOT NULL) < 250 THEN RAISE EXCEPTION 'Family seed count validation failed'; END IF;
    IF (SELECT count(*) FROM tours_tour WHERE external_id IS NOT NULL) < 400 THEN RAISE EXCEPTION 'Tour seed count validation failed'; END IF;
    IF (SELECT count(*) FROM tours_tourevent WHERE external_id IS NOT NULL) < 941 THEN RAISE EXCEPTION 'Tour event seed count validation failed'; END IF;
    IF (SELECT count(*) FROM reports_costbasis WHERE external_id IS NOT NULL) < 96 THEN RAISE EXCEPTION 'Cost basis seed count validation failed'; END IF;
END $$;

COMMIT;
